<body>
  <a class="skip-link" href="#maincontent">Skip to main content</a>

  <header>
    <div class="hero">
      <p class="eyebrow" style="margin:0 0 .45rem;color:#c8d4ff;font-weight:700;letter-spacing:.08em;text-transform:uppercase;font-size:.8rem;">Interactive quiz</p>
      <h1>Computer Languages Quiz</h1>
      <p class="lede">Pick every answer that applies for each question. When you’re ready, submit to see your score and a quick summary.</p>
    </div>
  </header>

  <main id="maincontent" tabindex="-1">
    <div id="app"></div>
  </main>

  <footer>
    Built with native checkboxes so each answer stays independently selectable and keyboard friendly.
  </footer>

  <script>
    const questions = [
      {
        id: 'q1',
        title: 'Which of these are programming languages?',
        helpText: 'Select every option that applies.',
        options: [
          { id: 'q1-python', label: 'Python', correct: true },
          { id: 'q1-javascript', label: 'JavaScript', correct: true },
          { id: 'q1-html', label: 'HTML', correct: false },
          { id: 'q1-css', label: 'CSS', correct: false },
        ],
      },
      {
        id: 'q2',
        title: 'Which of these are statically typed languages?',
        options: [
          { id: 'q2-typescript', label: 'TypeScript', correct: true },
          { id: 'q2-rust', label: 'Rust', correct: true },
          { id: 'q2-ruby', label: 'Ruby', correct: false },
          { id: 'q2-bash', label: 'Bash', correct: false },
        ],
      },
      {
        id: 'q3',
        title: 'Which of these are often used for scripting or automation?',
        options: [
          { id: 'q3-python', label: 'Python', correct: true },
          { id: 'q3-bash', label: 'Bash', correct: true },
          { id: 'q3-c', label: 'C', correct: false },
          { id: 'q3-swift', label: 'Swift', correct: false },
        ],
      }
    ];

    function h(tagName, attributes, ...children) {
      const element = document.createElement(tagName);
      for (const [key, value] of Object.entries(attributes || {})) {
        if (value == null || value === false) continue;
        if (key === 'className') {
          element.className = value;
        } else if (key === 'dataset') {
          Object.assign(element.dataset, value);
        } else if (key.startsWith('aria-') || key === 'role' || key === 'type' || key === 'name' || key === 'id' || key === 'for' || key === 'value' || key === 'tabindex' || key === 'hidden') {
          element.setAttribute(key, value);
        } else if (key in element) {
          element[key] = value;
        } else {
          element.setAttribute(key, value);
        }
      }

      const flatChildren = children.flat();
      for (const child of flatChildren) {
        if (child == null || child === false) continue;
        element.appendChild(
          child instanceof Node ? child : document.createTextNode(String(child))
        );
      }
      return element;
    }

    function Choice(questionId, option) {
      return h(
        'label',
        { className: 'option', for: option.id },
        h('input', {
          id: option.id,
          name: questionId,
          type: 'checkbox',
          value: option.label,
          dataset: { correct: String(option.correct) },
        }),
        h('span', null, option.label)
      );
    }

    function Question(question, index) {
      const describedBy = question.helpText ? `${question.id}-help` : undefined;
      return h(
        'div',
        { className: 'form-field' },
        h(
          'fieldset',
          describedBy ? { 'aria-describedby': describedBy } : {},
          h('legend', null, `${index + 1}. ${question.title}`),
          question.helpText ? h('p', { className: 'help-text', id: describedBy }, question.helpText) : null,
          h('div', { className: 'options' }, question.options.map((option) => Choice(question.id, option)))
        )
      );
    }

    function App() {
      const form = h('form', { className: 'quiz-form', id: 'quiz-form', novalidate: true });
      const result = h('div', { className: 'result', id: 'result', role: 'status', 'aria-live': 'polite', 'aria-atomic': 'true', hidden: true });

      form.append(...questions.map((question, index) => Question(question, index)));
      form.append(
        h('div', { className: 'submit-row' }, h('button', { type: 'submit' }, 'Submit quiz')),
        result
      );

      form.addEventListener('submit', (event) => {
        event.preventDefault();

        let score = 0;
        const lines = questions.map((question, index) => {
          const chosen = Array.from(form.querySelectorAll(`input[name="${question.id}"]:checked`)).map((input) => input.value);
          const correct = question.options.filter((option) => option.correct).map((option) => option.label);
          const matched = chosen.length === correct.length && [...chosen].sort().every((value, choiceIndex) => value === [...correct].sort()[choiceIndex]);

          if (matched) score += 1;

          return `${index + 1}. ${question.title} — ${matched ? 'correct' : 'not quite'} (${chosen.length ? chosen.join(', ') : 'no answers selected'})`;
        });

        result.hidden = false;
        result.innerHTML = `
          <p><strong>${score} / ${questions.length}</strong> correct.</p>
          <ul>${lines.map((line) => `<li>${line}</li>`).join('')}</ul>
        `;
      });

      return form;
    }

    document.getElementById('app').appendChild(App());
  </script>
</body>
</html>
